CREATE TABLE "activities" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color" INTEGER NOT NULL, "icon" TEXT NOT NULL DEFAULT 'circle', "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "sessions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "activity_id" INTEGER NOT NULL REFERENCES activities (id), "note" TEXT NOT NULL DEFAULT '', "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "skin_id" TEXT NULL);
CREATE TABLE "segments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "session_id" INTEGER NOT NULL REFERENCES sessions (id) ON DELETE CASCADE, "is_pause" INTEGER NOT NULL CHECK ("is_pause" IN (0, 1)), "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "deadline_at" INTEGER NULL, "deadline_kind" TEXT NULL);
CREATE TABLE "prefs" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "purchases" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "skin_id" TEXT NOT NULL UNIQUE, "price" INTEGER NOT NULL, "purchased_at" INTEGER NOT NULL);
CREATE TABLE "todo_categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color" INTEGER NOT NULL, "sort" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "todos" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "parent_id" INTEGER NULL REFERENCES todos (id) ON DELETE CASCADE, "category_id" INTEGER NULL REFERENCES todo_categories (id) ON DELETE SET NULL, "title" TEXT NOT NULL, "notes" TEXT NOT NULL DEFAULT '', "due" INTEGER NULL, "has_time" INTEGER NOT NULL DEFAULT 0 CHECK ("has_time" IN (0, 1)), "priority" INTEGER NOT NULL DEFAULT 4, "recurrence" TEXT NULL, "remind_before" INTEGER NULL, "completed_at" INTEGER NULL, "sort" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "horizon" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "notes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "body" TEXT NOT NULL, "color" INTEGER NULL, "date" INTEGER NULL, "has_time" INTEGER NOT NULL DEFAULT 0 CHECK ("has_time" IN (0, 1)), "remind" INTEGER NOT NULL DEFAULT 0 CHECK ("remind" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL);
CREATE TABLE "custom_skins" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "spec" TEXT NOT NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "created_at" INTEGER NOT NULL);